// Authored completed demo fixture; applied by the script, not generated by a model.
export function listContacts(rows, tenantId) {
 return rows.filter(row => row.tenantId === tenantId && !row.archived);
}
export function archiveContact(rows, tenantId, id) {
 const row = rows.find(row => row.tenantId === tenantId && row.id === id);
 if (!row) return false;
 row.archived = true;
 return true;
}
